vec2 clouds_altocumulus_scattering(
    float density,
    float light_optical_depth,
    float sky_optical_depth,
    float ground_optical_depth,
    float extinction_coeff,
    float scattering_coeff,
    float step_transmittance,
    float cos_theta,
    float bounced_light
) {
