        vec3 ray_pos = ray_origin + ray_step * i;

        float altitude_fraction =
            (length(ray_pos) - clouds_altocumulus_radius) *
            rcp(clouds_altocumulus_thickness);

        float density = clouds_altocumulus_density(ray_pos);

        if (density < eps) {
