            ray_pos,
            light_dir,
            hash.x,
            lighting_steps
        );
        float sky_optical_depth = clouds_altocumulus_optical_depth(
            ray_pos,
            sky_dir,
            hash.y,
            ambient_steps
        );
        float ground_optical_depth =
            mix(density, 1.0, clamp01(altitude_fraction * 2.0 - 1.0)) *
            altitude_fraction *
            clouds_altocumulus_thickness; // guess optical depth to the ground
                                          // using altitude fraction and density
                                          // from this sample

        scattering +=
            clouds_altocumulus_scattering(
                density,
                light_optical_depth,
                sky_optical_depth,
                ground_optical_depth,
                extinction_coeff,
                scattering_coeff,
                step_transmittance,
                cos_theta,
                bounced_light
