float clouds_altocumulus_density(vec3 pos) {
    const float wind_angle = CLOUDS_ALTOCUMULUS_WIND_ANGLE * degree;
    const vec2 wind_velocity =
        CLOUDS_ALTOCUMULUS_WIND_SPEED * vec2(cos(wind_angle), sin(wind_angle));

